document.addEventListener("DOMContentLoaded",()=>{const e=[{label:"Height",value:"5,289 m",detail:"Friendship Peak is listed in the issue as a 5,289 metre mountain."},{label:"State",value:"Himachal Pradesh",detail:"The peak belongs to the Himachal Pradesh mountain landscape."},{label:"Range",value:"Pir Panjal",detail:"The issue identifies Friendship Peak with the Pir Panjal range."},{label:"Known for",value:"Popular trekking destination",detail:"Friendship Peak is widely known as a scenic high-altitude trekking and climbing objective."},{label:"Nearest hub",value:"Manali region",detail:"The peak is commonly associated with the Kullu-Manali side of Himachal Pradesh."},{label:"Page focus",value:"Trekking guide + nature",detail:"The page combines natural beauty, facts, trekking guidance, safety, and gallery cards."}],a=[{title:"Trail character",text:"Friendship Peak routes are known for forests, alpine meadows, moraine zones, snow patches, and broad mountain views."},{title:"Fitness level",text:"Trekkers should be prepared for altitude, long walking days, cold nights, and changing weather."},{title:"Skills and support",text:"Use trained guides for snow sections, route decisions, weather checks, equipment, and emergency planning."},{title:"Responsible trekking",text:"Carry waste back, protect meadows, respect local communities, and avoid unsafe shortcuts."}],n=e=>String(e).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");document.getElementById("facts-grid").innerHTML=e.map(e=>`\n    <article class="fact-card">\n      <span>${n(e.label)}</span>\n      <strong>${n(e.value)}</strong>\n      <p>${n(e.detail)}</p>\n    </article>\n  `).join(""),document.getElementById("highlight-grid").innerHTML=[{title:"Accessible learning profile",text:"Friendship Peak is a recognisable mountain for users learning about Himachal trekking destinations."},{title:"Natural beauty",text:"The page highlights forests, alpine meadows, snow slopes, and scenic Pir Panjal views."},{title:"Safety-first guide",text:"Trekking information is written as awareness guidance, not as technical route instructions."},{title:"Landing integration",text:"A helper script adds a Mountains landing-page card and route link when matching files are present."}].map((e,a)=>`\n    <article class="highlight-card">\n      <span>0${a+1}</span>\n      <h3>${n(e.title)}</h3>\n      <p>${n(e.text)}</p>\n    </article>\n  `).join(""),document.getElementById("trek-grid").innerHTML=a.map((e,a)=>`\n    <article class="trek-card">\n      <span>0${a+1}</span>\n      <h3>${n(e.title)}</h3>\n      <p>${n(e.text)}</p>\n    </article>\n  `).join(""),document.getElementById("gallery-grid").innerHTML=[{title:"Pir Panjal view",image:"../../assets/travel_mountains.png",caption:"The Pir Panjal landscape is known for snow ridges and open Himalayan views."},{title:"Meadow approach",image:"../../assets/travel_hidden.png",caption:"Approach trails may include forests, meadows, and remote campsites."},{title:"Summit weather",image:"../../assets/hero_banner.png",caption:"Weather windows and altitude awareness are important for high mountain plans."},{title:"Trek camp",image:"../../assets/travel_mountains.png",caption:"Camp discipline and responsible travel protect fragile mountain environments."}].map(e=>`\n    <article class="gallery-card">\n      <img src="${n(e.image)}" alt="${n(e.title)}" onerror="this.src='../../assets/hero_banner.png'">\n      <div>\n        <h3>${n(e.title)}</h3>\n        <p>${n(e.caption)}</p>\n      </div>\n    </article>\n  `).join(""),window.FriendshipPeakMountainPage={facts:()=>[...e],trek:()=>[...a]}});